SELECT Document_ID, Template_ID, Template_Type_Code
FROM Templates
ORDER BY Document_ID, Template_ID;

SELECT NATIONALITY, COUNT(*) AS COUNTING
FROM people
GROUP BY NATIONALITY;

SELECT professional_id, role_code, email_address 
FROM Professionals
WHERE role_code NOT IN ('Employee', 'Veterenarian') AND email_address IS NULL;

SELECT Citizenship, COUNT(*) AS Number_of_Singers
FROM singer
GROUP BY Citizenship;
